ch']++;$x['goals']+=(int)($p['goals']??0);$x['assists']+=(int)($p['assists']??0);$x['motm']+=(int)($p['man_of_match']??0);$x['yellow']+=(int)($p['yellow_card']??0);$x['red']+=(int)($p['red_card']??0);$x['own_goals']+=(int)($p['own_goals']??0);if($p['rating']!==null){$x['rating_sum']+=(float)$p['rating'];$x['rating_count']++;}unset($x);}}$ids=array_keys($players);if($ids){$ph=implode(',',array_fill(0,count($ids),'?'));$codex=nexus_core_rows($core,"SELECT p.id,d.position,p.image_url FROM `IMC Player Codex Global` p LEFT JOIN `IMC Player Codex Global Data` d ON d.player_id=p.id WHERE p.id IN ($ph)",$ids);foreach($codex as $p)if(isset($players[(string)$p['id']])){$players[(string)$p['id']]['position']=$p['position'];$players[(string)$p['id']]['image_url']=$p['image_url'];}}foreach($players as &$p){$p['avg_rating']=$p['rating_count']?round($p['rating_sum']/$p['rating_count'],2):null;unset($p['rating_sum'],$p['rating_count']);}unset($p);out(['ok'=>true,'world'=>$world,'team'=>$team,'rows'=>array_values($players)]);}if($resource==='team_stats'){$team=(string)($_GET['team']??'');$season=nexus_season($core,$world,(string)($_GET['season']??''));$params=[$world,$team,$team];$where=nexus_date_where('match_date',$season,$params);$rows=nexus_core_rows($pdo,"SELECT match_date,home_sm_club_id,away_sm_club_id,home_score,away_score,team_stats_json,players_json FROM IMC_Site_Match_Report WHERE game_world_id=? AND (home_sm_club_id=? OR away_sm_club_id=?) AND home_score IS NOT NULL AND away_score IS NOT NULL $where ORDER BY match_date",$params);$s=['played'=>0,'wins'=>0,'draws'=>0,'losses'=>0,'gf'=>0,'ga'=>0,'possession'=>0,'shots'=>0,'shots_on_target'=>0,'corners'=>0,'yellow_cards'=>0,'red_cards'=>0,'player_rating_sum'=>0,'player_rating_count'=>0,'motm'=>0,'goals'=>0,'assists'=>0];foreach($rows as $r){$home=(string)$r['home_sm_club_id']===$team;$gf=(int)($home?$r['home_score']:$r['away_score']);$ga=(int)($home?$r['away_score']:$r['home_score']);$s['played']++;$s['gf']+=$gf;$s['ga']+=$ga;if($gf>$ga)$s['wins']++;elseif($gf===$ga)$s['draws']++;else$s['losses']++;$ts=json_decode((string)($r['team_stats_json']??''),true);$side=$home?'home':'away';$t=is_array($ts)?($ts[$side]??[]):[];foreach(['possession','total_shots'=>'shots','shots_on_target','corners','yellow_cards','red_cards'] as $k=>$v){if(is_int($k))$k=$v;$dest=is_int($v)?$k:$v;$s[$dest]+=(float)($t[$k]??0);}$ps=json_decode((string)($r['players_json']??''),true);if(is_array($ps))foreach($ps as $p)if(($p['team_side']??'')===$side){if($p['rating']!==null){$s['player_rating_sum']+=(float)$p['rating'];$s['player_rating_count']++;}$s['motm']+=(int)($p['man_of_match']??0);$s['goals']+=(int)($p['goals']??0);$s['assists']+=(int)($p['assists']??0);}}$n=max(1,$s['played']);$s['win_pct']=round($s['wins']*100/$n,1);$s['goal_diff']=$s['gf']-$s['ga'];foreach(['gf','ga','possession','shots','shots_on_target','corners','yellow_cards','red_cards'] as $k)$s[$k.'_avg']=round($s[$k]/$n,2);$s['shot_accuracy']=$s['shots']?round($s['shots_on_target']*100/$s['shots'],1):0;$s['player_rating_avg']=$s['player_rating_count']?round($s['player_rating_sum']/$s['player_rating_count'],2):0;unset($s['player_rating_sum'],$s['player_rating_count']);out(['ok'=>true,'world'=>$world,'team'=>$team,'stats'=>$s]);}if($resource==='teams'){$clubs=nexus_core_rows($core,'SELECT m.*,c.* FROM `IMC Game World Club Mapping` m LEFT JOIN `IMC Club Codex Global` c ON c.id=m.`Club ID` WHERE m.`Game World`=? ORDER BY m.`Club Name`',[$world]);$nations=nexus_core_rows($core,'SELECT m.*,n.* FROM `IMC Game World National Team Mapping` m LEFT JOIN `IMC National Team Codex Global` n ON n.id=m.`National Team ID` WHERE m.`Game World`=? ORDER BY m.`National Team Name`',[$world]);out(['ok'=>true,'world'=>$world,'clubs'=>$clubs,'nations'=>$nations]);}$allowed=['results','schedule','transfers','players'];if(!in_array($resource,$allowed,true))out(['ok'=>false,'error'=>'invalid_resource'],422);$_GET['world']=$world;$_GET['resource']=$resource;ob_start();include 